 public static void Validate(){var m=UnityEngine.Object.FindAnyObjectByType<PongMatch>();if(m==null){EditorSceneManager.OpenScene(Scene);m=UnityEngine.Object.FindAnyObjectByType<PongMatch>();}if(m==null||m.cups.Length!=20||m.cups.Any(c=>c.shell==null||c.shell.convex||c.visual==null||c.liquid==null)||m.replay.sources.Length!=23||m.pads.Length!=2||m.shot==null||m.table==null||m.floor==null||m.cupDiagrams.Length!=2)throw new Exception("Beer Pong references/physical hollow cups incomplete");Debug.Log("PONG_NATIVE_SCENE_VALIDATED");}
